import * as fs from "fs";
import * as path from "path";

import * as OurTypes from "../src/types";
import * as OurXmlization from "../src/xmlization";

import * as TestCommon from "./common";

/**
 * Load a maximal XML example of {@link types.SomeItem}
 * from the test data directory.
 */
export function loadMaximalSomeItem(
): OurTypes.SomeItem {
  const aPath = path.join(
    TestCommon.TEST_DATA_DIR,
    "Xml",
    "Expected",
    "someItem",
    "maximal.xml"
  );

  const text = fs.readFileSync(aPath, "utf-8");

  const instanceOrError = OurXmlization.fromXmlString(
    text
  );
  expect(instanceOrError.error).toBeNull();
  const instance = instanceOrError.mustValue();

  const casted = OurTypes.asSomeItem(instance);
  if (casted === null) {
    throw new Error(
      `Expected instance of SomeItem in ${aPath}, ` +
      `but got: ${typeof instance}`
    );
  }
  return casted;
}

